package org.eclipse.rdf4j.http.client;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.http.client.spi.NameValuePair;
import org.eclipse.rdf4j.http.protocol.Protocol;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/** The {@code lmdb-result-cache} query parameter is sent exactly when the session asks for the result cache. */
class RDF4JProtocolSessionResultCacheTest {

	private SharedHttpClientSessionManager sessionManager;
	private RDF4JProtocolSession session;

	@BeforeEach
	void setUp() {
		sessionManager = new SharedHttpClientSessionManager();
		session = sessionManager.createRDF4JProtocolSession("http://localhost:1/rdf4j-server");
	}

	@AfterEach
	void tearDown() {
		session.close();
		sessionManager.shutDown();
	}

	@Test
	void theParameterIsSentOnlyWhenRequested() {
		assertThat(parameters()).doesNotContainKey(Protocol.LMDB_RESULT_CACHE_PARAM_NAME);

		session.setLmdbResultCacheRequested(true);
		assertThat(parameters()).containsEntry(Protocol.LMDB_RESULT_CACHE_PARAM_NAME, "true");

		session.setLmdbResultCacheRequested(false);
		assertThat(parameters()).doesNotContainKey(Protocol.LMDB_RESULT_CACHE_PARAM_NAME);
	}

	private Map<String, String> parameters() {
		List<NameValuePair> parameters = session.getQueryMethodParameters(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s ?p ?o }", null, null, true, 0);
		return parameters.stream().collect(Collectors.toMap(NameValuePair::getName, NameValuePair::getValue));
	}
}
